```
import torch
import time
import os
from vllm import _custom_ops as ops

# Test shapes (M=Batch*SeqLen, K=In_Channels, N=Out_Channels)
SHAPES = [
    (16, 4096, 4096),   # Standard batch
    (32, 4096, 4096),   # Larger batch
    (64, 4096, 4096),   # Max block size N constraint
]
G = 128
SPLIT_K = 8
BASELINE_FILE = "awq_baseline_tensors.pt"

def generate_inputs(m, k, n):
    # Fixed seed guarantees identical tensors across branch checkouts
    torch.manual_seed(42)
    in_feats = torch.randn((m, k), dtype=torch.float16, device="cuda")
    # AWQ packs 8x 4-bit weights into 1x INT32
    qweight = torch.randint(-2000000000, 2000000000, (k, n // 8), dtype=torch.int32, device="cuda")
    scales = torch.randn((k // G, n), dtype=torch.float16, device="cuda") * 0.1
    qzeros = torch.randint(-2000000000, 2000000000, (k // G, n // 8), dtype=torch.int32, device="cuda")
    return in_feats, qweight, scales, qzeros

def benchmark(m, k, n, in_feats, qweight, scales, qzeros, warmup=10, iters=100):
    for _ in range(warmup):
        ops.awq_gemm(in_feats, qweight, scales, qzeros, SPLIT_K)

    torch.cuda.synchronize()
    start = time.perf_counter()
    for _ in range(iters):
        ops.awq_gemm(in_feats, qweight, scales, qzeros, SPLIT_K)
    torch.cuda.synchronize()

    return (time.perf_counter() - start) / iters * 1000 # ms

if __name__ == "__main__":
    is_baseline = not os.path.exists(BASELINE_FILE)
    saved_data = {} if is_baseline else torch.load(BASELINE_FILE)

    print(f"Mode: {'GENERATING BASELINE' if is_baseline else 'VERIFYING OPTIMIZATION'}\n")

    for m, k, n in SHAPES:
        in_feats, qweight, scales, qzeros = generate_inputs(m, k, n)

        # 1. Correctness
        out = ops.awq_gemm(in_feats, qweight, scales, qzeros, SPLIT_K)
        shape_key = f"{m}_{k}_{n}"

        if is_baseline:
            saved_data[shape_key] = out.clone()
        else:
            baseline_out = saved_data[shape_key]
            # Use a strict tolerance. FMA reordering might cause tiny FP16 drifts, 
            # but they should be well within 1e-3.
            is_close = torch.allclose(out, baseline_out, rtol=1e-2, atol=1e-3)
            max_diff = torch.max(torch.abs(out - baseline_out)).item()
            status = "✅ PASS" if is_close else "❌ FAIL"
            print(f"[{m}x{k}x{n}] Correctness: {status} (Max diff: {max_diff:.6f})")

        # 2. Benchmark
        avg_ms = benchmark(m, k, n, in_feats, qweight, scales, qzeros)
        print(f"[{m}x{k}x{n}] Latency: {avg_ms:.4f} ms\n")

    if is_baseline:
        torch.save(saved_data, BASELINE_FILE)
        print(f"Saved baselines to {BASELINE_FILE}. Now switch to your branch, recompile, and run again.")

